        .mall-item:hover, .map-location:hover { transform: translateY(-5px) scale(1.02); border-color: var(--border-color-hover); background: var(--bg-tab-active); box-shadow: 0 8px 25px -5px var(--shadow-color); }
        .mall-item-title, .map-location-title { font-weight: 700; color: var(--text-title); font-size: 1.1em; margin: 0 0 8px 0; }
        .mall-item-title::after, .map-location-title::after { content: ' >'; color: var(--accent-color); opacity: 0; transition: opacity 0.3s; }
        .mall-item:hover .mall-item-title::after, .map-location:hover .map-location-title::after { opacity: 1; }
        .mall-item-desc { color: var(--text-secondary); font-size: 0.9em; line-height: 1.5; flex-grow: 1; margin: 0; }
        .status-comment-card { z-index: 5; }
        .status-header { padding: 22px 28px; border-bottom: 1px solid var(--border-color); overflow: hidden; position: relative; }
        .status-header::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.05), transparent); background-size: 200% 100%; animation: gradientSweep 4s linear infinite; }
        .status-title { font-size: 1.5em; font-weight: 700; color: var(--text-title); margin: 0; }
        .status-details { display: flex; align-items: center; gap: 12px; margin-top: 14px; color: var(--text-secondary); font-size: 0.95em; }
        .status-indicator { width: 10px; height: 10px; border-radius: 50%; background-color: var(--accent-color); animation: livePulse 1.5s infinite ease-out; }
        .comments-title { font-size: 1.1em; font-weight: 600; color: var(--text-secondary); margin: 0; padding: 20px 28px 0; }
        .comments-section { padding: 15px 28px 28px; max-height: 480px; overflow-y: auto; scroll-behavior: smooth; }
        .comments-section::-webkit-scrollbar { width: 8px; }
        .comments-section::-webkit-scrollbar-track { background: transparent; }
        .comments-section::-webkit-scrollbar-thumb { background: var(--scrollbar-thumb); border-radius: 4px; }
        .comments-section::-webkit-scrollbar-thumb:hover { background: var(--scrollbar-thumb-hover); }
        .comment { --user-color: var(--text-user); display: flex; position: relative; margin-bottom: 18px; padding: 12px 18px 12px 30px; background: var(--bg-comment); border-radius: 12px; border: 1px solid transparent; transition: all 0.3s ease-out; animation: commentSlideIn 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards; opacity: 0; }
        .comment::before { content: ''; position: absolute; left: 12px; top: 12px; bottom: 12px; width: 3px; border-radius: 2px; background-color: var(--user-color); transition: background-color 0.3s; }
        .comment:hover { border-color: var(--border-color-hover); background: var(--bg-comment-hover); transform: translateY(-3px) scale(1.01); box-shadow: 0 8px 20px -5px rgba(0,0,0,0.1); }
        .comment-body { flex-grow: 1; }
        .comment-user { font-weight: 600; color: var(--user-color); margin-bottom: 5px; font-size: 0.95em; transition: color 0.3s; }
        .comment-text { color: var(--text-primary); line-height: 1.65; font-size: 0.95em; margin: 0; word-break: break-word; transition: color 0.3s; }
        .theme-switcher { position: absolute; top: 22px; right: 25px; z-index: 10; width: 36px; height: 36px; border-radius: 50%; background: var(--bg-comment); border: 1px solid var(--border-color); display: flex; justify-content: center; align-items: center; cursor: pointer; transition: all 0.3s ease; }
        .theme-switcher:hover { transform: scale(1.1) rotate(15deg); border-color: var(--border-color-hover); }
        .theme-switcher svg { width: 18px; height: 18px; fill: var(--theme-icon-fill); transition: fill 0.3s; }
        .theme-switcher .icon-sun { display: none; }
        .theme-switcher .icon-moon { display: block; }
        .light-theme .theme-switcher .icon-sun { display: block; }
        .light-theme .theme-switcher .icon-moon { display: none; }
        @media (max-width: 768px) {
            .container { gap: 18px; } .card { border-radius: 14px; }
