    <script>
        (function() {
            const randomId = "$RANDOM";
            const liveContainer = document.getElementById(`live-container-${randomId}`);
            if (!liveContainer) return;

            const escapeHTML = (str) => str.toString().replace(/</g, "&lt;").replace(/>/g, "&gt;");

            const triggerQuickReply = (text) => {
                if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${text}|/trigger`);
                } else {
                    console.log('SillyTavern environment not detected. Would send:', text);
                }
            };

            const smoothScrollTo = (element) => {
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            };

            const mainCard = document.getElementById(`main-card-${randomId}`);
            const themeToggleButton = document.getElementById(`theme-toggle-btn-${randomId}`);
            if (themeToggleButton) {
                const themeStorageKey = 'sillytavern_live_theme_v10';
                const applyTheme = (theme) => {
                    liveContainer.classList.toggle('light-theme', theme === 'light');
                    liveContainer.classList.toggle('dark-theme', theme !== 'light');
                };
                applyTheme(localStorage.getItem(themeStorageKey) || 'light');
                themeToggleButton.addEventListener('click', () => {
                    const newTheme = liveContainer.classList.contains('dark-theme') ? 'light' : 'dark';
                    localStorage.setItem(themeStorageKey, newTheme);
                    applyTheme(newTheme);
                });
            }

            const tabControls = document.getElementById(`tab-controls-${randomId}`);
            if (tabControls) {
                tabControls.addEventListener('click', (e) => {
                    const button = e.target.closest('.tab-btn');
                    if (button) {
                        const tabId = button.dataset.tab;
                        const activeTab = tabControls.querySelector('.active');
                        if (activeTab) activeTab.classList.remove('active');
                        button.classList.add('active');

                        liveContainer.querySelectorAll('.tab-content-panel').forEach(panel => {
                            panel.classList.remove('active');
                        });
                        const activePanel = document.getElementById(`tab-content-${tabId}-${randomId}`);
                        if (activePanel) activePanel.classList.add('active');

                        smoothScrollTo(mainCard);
                    }
                });
            }

            const mallGrid = document.getElementById(`mall-grid-container-${randomId}`);
            if (mallGrid) {
                mallGrid.addEventListener('click', (e) => {
                    const mallItem = e.target.closest('.mall-item');
                    if (!mallItem) return;
                    const command = mallItem.dataset.command;
                    if (command) {
                        triggerQuickReply(command);
                    }
                });
            }

            const mapGrid = document.getElementById(`map-grid-container-${randomId}`);
            if (mapGrid) {
                mapGrid.addEventListener('click', (e) => {
                    const mapLocation = e.target.closest('.map-location');
                    if (!mapLocation) return;
                    const locationName = mapLocation.dataset.location;
                    if (locationName) {
                        const command = `前往 ${locationName.trim()}`;
                        triggerQuickReply(command);
                    }
                });
            }

            const statusCard = liveContainer.querySelector('.status-comment-card');
            const commentsContainer = document.getElementById(`comments-container-${randomId}`);
            const commentsTitle = document.getElementById(`comments-title-${randomId}`);
            const liveTitleElem = statusCard ? statusCard.querySelector('.status-title') : null;
            const liveTimeElem = statusCard ? statusCard.querySelector('.status-time') : null;

            const liveTitle = liveTitleElem ? liveTitleElem.textContent.trim() : '';
            const liveTime = liveTimeElem ? liveTimeElem.textContent.trim() : '';
            const commentsDataRaw = `$5`;
            const instructionRegex = /{{\s*[\s\S]*?}}\s*/;
            const cleanedCommentsRaw = commentsDataRaw.replace(instructionRegex, '').trim();

            if (!liveTitle && !liveTime && !cleanedCommentsRaw) {
                if (statusCard) statusCard.style.display = 'none';
                return;
            }

            if (!commentsContainer || !cleanedCommentsRaw) {
                if(commentsTitle) commentsTitle.style.display = 'none';
            } else {
                const commentsData = cleanedCommentsRaw.split('\n').map(line => {
                    if (!line.trim()) return null;
                    const separatorIndex = line.indexOf(':');
                    if (separatorIndex <= 0) return null;
                    const user = line.substring(0, separatorIndex).trim();
                    const comment = line.substring(separatorIndex + 1).trim();
                    return comment ? { user, comment } : null;
                }).filter(Boolean);

                if (commentsData.length === 0) {
                    if(commentsTitle) commentsTitle.style.display = 'none';
                } else {
                    let currentIndex = 0;
                    const intervalId = setInterval(() => {
                        if (currentIndex >= commentsData.length) {
                            clearInterval(intervalId);
                            return;
                        }
                        const data = commentsData[currentIndex];
                        let hash = 0;
                        for (let i = 0; i < data.user.length; i++) {
                            hash = data.user.charCodeAt(i) + ((hash << 5) - hash);
                            hash &= hash;
                        }
                        const h = 200 + (hash % 40), s = 60 + (Math.abs(hash) % 20), l = 75 + (Math.abs(hash) % 10);
                        const color = `hsl(${h}, ${s}%, ${l}%)`;
                        const commentElement = document.createElement('div');
                        commentElement.className = 'comment';
                        commentElement.style.animationDelay = `${Math.min(currentIndex * 0.1, 0.5)}s`;
                        commentElement.style.setProperty('--user-color', color);
                        commentElement.innerHTML = `<div class="comment-body"><div class="comment-user">${escapeHTML(data.user)}</div><p class="comment-text">${escapeHTML(data.comment)}</p></div>`;
                        commentsContainer.appendChild(commentElement);
                        commentsContainer.scrollTop = commentsContainer.scrollHeight;
                        currentIndex++;
                    }, 2000);
                }
            }
        })();
    </script>
</body>
</html>
